import{_ as i,C as o,o as t,c as r,a2 as n,b as l,w as a,a as d,E as c,a3 as h}from"./chunks/framework.CZqXuAiL.js";const v=JSON.parse('{"title":"Sentinel for Pterodactyl","description":"Fleet-wide security monitoring and enforcement for Pterodactyl — 12 detectors, graduated enforcement, central threat intel, and panel-managed config pushed to every Wings node.","frontmatter":{"title":"Sentinel for Pterodactyl","description":"Fleet-wide security monitoring and enforcement for Pterodactyl — 12 detectors, graduated enforcement, central threat intel, and panel-managed config pushed to every Wings node.","head":[["meta",{"name":"og:title","content":"Sentinel for Pterodactyl — Fleet-Wide Security Monitoring and Enforcement"}],["meta",{"name":"og:description","content":"A Laravel panel addon (the brain) plus a static Go agent on each Wings node (the sensor/enforcer). Twelve detectors, graduated enforcement, central threat intel."}]]},"headers":[],"relativePath":"pterodactyl-sentinel/index.md","filePath":"pterodactyl-sentinel/index.md","lastUpdated":1785525039000}'),p={name:"pterodactyl-sentinel/index.md"};function g(u,e,f,b,m,y){const s=o("Mermaid");return t(),r("div",null,[e[1]||(e[1]=n('<h1 id="sentinel-for-pterodactyl" tabindex="-1">Sentinel for Pterodactyl <a class="header-anchor" href="#sentinel-for-pterodactyl" aria-label="Permalink to &quot;Sentinel for Pterodactyl&quot;">​</a></h1><p><strong>Fleet-wide security monitoring and enforcement for Pterodactyl panels</strong> — a Laravel panel addon (the brain) plus a static Go agent on each Wings node (the sensor/enforcer). Sentinel watches every container on every node for cryptominers, port scans, outbound DDoS, zip bombs, privilege escalation, abuse tooling and malware, then contains what it finds with a graduated rules engine — all configured once in your admin panel and pushed, versioned, to the whole fleet.</p><div class="tip custom-block" style="margin-top:1.5rem;"><p><strong>Built for PingLess Studios</strong><a href="https://studio.pingless.org" target="_blank" rel="noreferrer">studio.pingless.org</a> · Panel addon + node agent, installed separately</p></div><hr><h2 id="architecture" tabindex="-1">Architecture <a class="header-anchor" href="#architecture" aria-label="Permalink to &quot;Architecture&quot;">​</a></h2>',5)),(t(),l(h,null,{default:a(()=>[c(s,{id:"mermaid-15",class:"mermaid",graph:"flowchart%20LR%0A%20%20%20%20subgraph%20Panel%5B%22Pterodactyl%20Panel%22%5D%0A%20%20%20%20%20%20%20%20ADDON%5B%22Sentinel%20addon%3Cbr%2F%3E(Blueprint%3A%20pterodactylsentinel)%22%5D%0A%20%20%20%20%20%20%20%20DB%5B(%22sentinel_*%20tables%3Cbr%2F%3Etokens%20%C2%B7%20events%20%C2%B7%20hashes%20%C2%B7%20scans%20%C2%B7%20quarantines%20%C2%B7%20settings%22)%5D%0A%20%20%20%20%20%20%20%20UI%5B%22Admin%20UI%3Cbr%2F%3EDashboard%20%C2%B7%20Detections%20%C2%B7%20Nodes%20%C2%B7%20Servers%20%C2%B7%20Scans%20%C2%B7%20Intel%20%C2%B7%20Quarantine%20%C2%B7%20Settings%22%5D%0A%20%20%20%20%20%20%20%20INTEL%5B%22Threat%20intel%20DB%3Cbr%2F%3E(confirmed%20hash%20blocklist%20%2B%20YARA%20bundle)%22%5D%0A%20%20%20%20%20%20%20%20ADDON%20--%3E%20DB%0A%20%20%20%20%20%20%20%20UI%20--%3E%20ADDON%0A%20%20%20%20%20%20%20%20ADDON%20--%3E%20INTEL%0A%20%20%20%20end%0A%0A%20%20%20%20subgraph%20Node1%5B%22Wings%20Node%201%22%5D%0A%20%20%20%20%20%20%20%20AGENT1%5B%22sentinel%20agent%3Cbr%2F%3E(static%20Go%20binary)%22%5D%0A%20%20%20%20%20%20%20%20DET1%5B%2212%20detectors%3Cbr%2F%3Eminer%20%C2%B7%20portscan%20%C2%B7%20ddos%20%C2%B7%20zipbomb%20%C2%B7%20exploit%20%C2%B7%20abuse%3Cbr%2F%3Eonaccess%20%C2%B7%20yara%20%C2%B7%20fim%20%C2%B7%20trivy%20%C2%B7%20containerscan%20%C2%B7%20volumescan%22%5D%0A%20%20%20%20%20%20%20%20ENG1%5B%22engine%3Cbr%2F%3Ecooldown%20%E2%86%92%20rules%20%E2%86%92%20actions%20%E2%86%92%20spool%22%5D%0A%20%20%20%20%20%20%20%20C1%5B%22Server%20containers%22%5D%0A%20%20%20%20%20%20%20%20AGENT1%20--%3E%20DET1%20--%3E%20ENG1%0A%20%20%20%20%20%20%20%20ENG1%20--%3E%7C%22kill%20%2F%20quarantine%20%2F%20pause%20%2F%20stop%22%7C%20C1%0A%20%20%20%20end%0A%0A%20%20%20%20subgraph%20Node2%5B%22Wings%20Node%202%22%5D%0A%20%20%20%20%20%20%20%20AGENT2%5B%22sentinel%20agent%22%5D%0A%20%20%20%20%20%20%20%20C2%5B%22Server%20containers%22%5D%0A%20%20%20%20%20%20%20%20AGENT2%20--%3E%20C2%0A%20%20%20%20end%0A%0A%20%20%20%20AGENT1%20--%3E%7C%22register%20(one-time%20pairing)%22%7C%20ADDON%0A%20%20%20%20AGENT1%20--%3E%7C%22heartbeat%20every%2030s%22%7C%20ADDON%0A%20%20%20%20AGENT1%20--%3E%7C%22event%20batches%20%2B%20intel%20hash%20submissions%22%7C%20ADDON%0A%20%20%20%20ADDON%20--%3E%7C%22config%20push%20(POST%20%2Fapi%2Fv1%2Fconfig)%22%7C%20AGENT1%0A%20%20%20%20ADDON%20--%3E%7C%22scan%20triggers%20%C2%B7%20containment%20actions%22%7C%20AGENT1%0A%20%20%20%20INTEL%20--%3E%7C%22confirmed%20hashes%20%2B%20YARA%20rules%3Cbr%2F%3Edistributed%20on%20config%20sync%22%7C%20AGENT1%0A%20%20%20%20AGENT2%20--%3E%7C%22register%20%C2%B7%20heartbeat%20%C2%B7%20events%22%7C%20ADDON%0A%20%20%20%20ADDON%20--%3E%7C%22config%20push%20%C2%B7%20scans%22%7C%20AGENT2%0A"})]),fallback:a(()=>[...e[0]||(e[0]=[d(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=n(`<p>The node agent authenticates to the panel with a per-node 64-hex bearer token; the panel uses the same token when calling back into the node. Both directions use a single documented API contract with a <code>{success, data, error, meta}</code> envelope everywhere. The node holds exactly one secret (its pairing token) — Discord webhooks, SMTP credentials and intel feed URLs live only in the panel database.</p><h3 id="the-intel-loop" tabindex="-1">The intel loop <a class="header-anchor" href="#the-intel-loop" aria-label="Permalink to &quot;The intel loop&quot;">​</a></h3><ol><li>A node&#39;s detectors hash a suspicious file (SHA-256) and submit it to the panel.</li><li>The panel upserts the hash into <code>sentinel_hashes</code>, tracking which distinct nodes reported it.</li><li>When a hash reaches the confirm threshold (default: 3 distinct nodes), or an admin confirms it manually, or it arrives via bulk import, it becomes <strong>confirmed</strong>.</li><li>The confirmed set (plus the YARA rule bundle) is distributed back to every node on the next config sync, where the on-access scanner and volume scans block it fleet-wide.</li></ol><hr><h2 id="key-features" tabindex="-1">Key Features <a class="header-anchor" href="#key-features" aria-label="Permalink to &quot;Key Features&quot;">​</a></h2><ul><li><strong>12 detectors on every node.</strong> Cryptominers (CPU heuristics, known binaries, pool-port connections), port scans, outbound DDoS/stress tools, zip bombs (ratio + hot-write triggers), privilege escalation / container escapes / reverse shells, abuse tooling (tor, proxies, VPNs, tunnels, mailers, IRC), on-access malware scanning (fsnotify + hash blocklist + YARA), scheduled YARA sweeps, file-integrity monitoring, image CVE scans (trivy), container scans (processes, log indicators, npm/WhatsApp bots, undersized <code>server.jar</code>, cache artifacts), and full volume pattern scans.</li><li><strong>Graduated enforcement.</strong> A rules engine maps (category, minimum severity) to actions: alert, quarantine file, delete file, kill process, pause container, stop container, suspend server. Local actions run on the node instantly; <code>suspend_server</code> is executed panel-side via Pterodactyl&#39;s <code>SuspensionService</code>, so it is panel-authoritative and survives node restarts.</li><li><strong>Global dry-run mode.</strong> Every detection is logged and reported, but no containment action is taken — the safe way to roll out and tune before going live.</li><li><strong>Central threat intel.</strong> Nodes submit SHA-256 hashes; a hash reported by enough distinct nodes (or confirmed by an admin, or bulk-imported from a file/URL) is distributed back to every node&#39;s blocklist.</li><li><strong>Panel-managed, versioned config.</strong> Every detector knob, rule, whitelist entry and limit is edited once in the admin UI. On save, <code>config_version</code> increments and the panel pushes to every online node; offline nodes reconcile on their next heartbeat. Apply is atomic (validate, write temp, rename, reload) and a bad push can never take effect.</li><li><strong>Graceful degradation.</strong> Panel down? Nodes keep enforcing with their last-known config and spool events to a bounded on-disk queue (cap ~10k), flushing when the panel returns. Node down? The panel marks it offline and keeps its last data.</li><li><strong>Per-server attribution.</strong> Every event — including file-path-only detections — is resolved to the exact Pterodactyl server UUID via docker labels, container name, or volume path, and muted servers suppress actions and alerts while still recording events.</li><li><strong>Native admin UI.</strong> Eight AdminLTE tabs inside your panel: Dashboard, Detections, Nodes, Servers, Scans, Intel, Quarantine, and a tabbed Settings editor with per-node overrides.</li><li><strong>Quarantine ledger.</strong> Quarantined files across all nodes are tracked in one table with admin-initiated restore and delete.</li></ul><hr><h2 id="quick-install" tabindex="-1">Quick Install <a class="header-anchor" href="#quick-install" aria-label="Permalink to &quot;Quick Install&quot;">​</a></h2><p>Both halves are installed separately. Panel first, then each node.</p><p><strong>Panel (Blueprint):</strong></p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># place pterodactylsentinel-v1.0.0.blueprint in /var/www/pterodactyl, then:</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">blueprint</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -i</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pterodactylsentinel-v1.0.0</span></span></code></pre></div><p><strong>Panel (standalone, no Blueprint):</strong></p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> bash</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> standalone/install.sh</span></span></code></pre></div><p><strong>Each Wings node (as root):</strong></p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> bash</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> node-module/install.sh</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   # prompts for panel URL + the per-node token from Sentinel &gt; Nodes</span></span></code></pre></div><p>Head to the <a href="./getting-started/installation">Installation guide</a> for prerequisites, verification and troubleshooting, or the <a href="./getting-started/quick-start">Quick Start</a> for the five-minute path.</p><hr><h2 id="how-pairing-works" tabindex="-1">How Pairing Works <a class="header-anchor" href="#how-pairing-works" aria-label="Permalink to &quot;How Pairing Works&quot;">​</a></h2><ol><li><strong>Token issued.</strong> Open <strong>Admin → Sentinel → Nodes</strong>. Every Pterodactyl node gets a row with a generated 64-hex token. The panel stores a bcrypt hash for verification plus an encrypted copy so you can re-view (or reset) it later.</li><li><strong>Node installed.</strong> Run <code>node-module/install.sh</code> as root on the Wings node. It prompts for the panel URL and token, writes <code>/etc/sentinel/config.yaml</code> and <code>/etc/sentinel/token</code> (both <code>0600</code>), and starts the <code>sentinel-node</code> systemd service.</li><li><strong>Node registers.</strong> The agent calls <code>POST /api/sentinel/node/register</code> (retrying with backoff). The panel verifies the bearer token, records the node&#39;s reachable API URL, flips the node to <strong>online</strong>, and pushes the current config.</li><li><strong>Steady state.</strong> The node heartbeats every 30 s. When the config changes in the panel, the panel pushes it directly and the heartbeat response carries the new <code>config_version</code>; a stale node pulls and re-applies. Resetting a token kills the old one instantly — the node goes offline until re-paired.</li></ol><hr><h2 id="comparison-with-standalone-node-scanners" tabindex="-1">Comparison with Standalone Node Scanners <a class="header-anchor" href="#comparison-with-standalone-node-scanners" aria-label="Permalink to &quot;Comparison with Standalone Node Scanners&quot;">​</a></h2><p>Sentinel shares DNA with sonar/radar-style standalone node scanners (single-host daemons that detect miners and abuse), but is purpose-built for multi-node Pterodactyl fleets.</p><table tabindex="0"><thead><tr><th>Capability</th><th style="text-align:center;">Sentinel for Pterodactyl</th><th style="text-align:center;">Standalone node scanners</th></tr></thead><tbody><tr><td>Pterodactyl server attribution</td><td style="text-align:center;">Every event mapped to a server UUID</td><td style="text-align:center;">Container-level or none</td></tr><tr><td>Central threat intel</td><td style="text-align:center;">Confirmed hashes distributed to every node</td><td style="text-align:center;">Local-only blocklists</td></tr><tr><td>Configuration</td><td style="text-align:center;">Edited once in the panel, versioned, pushed to all nodes</td><td style="text-align:center;">Hand-edited file per host</td></tr><tr><td>Enforcement</td><td style="text-align:center;">Graduated rules; panel-authoritative suspension</td><td style="text-align:center;">Local kill/stop only</td></tr><tr><td>Panel downtime</td><td style="text-align:center;">Nodes keep enforcing, spool events to disk</td><td style="text-align:center;">Usually hard-fails or stops reporting</td></tr><tr><td>Secrets on nodes</td><td style="text-align:center;">One revocable pairing token</td><td style="text-align:center;">Often a panel API key</td></tr><tr><td>Admin UI</td><td style="text-align:center;">Dashboard, detections, intel DB, quarantine ledger</td><td style="text-align:center;">CLI/log files</td></tr></tbody></table><hr><h2 id="where-next" tabindex="-1">Where Next <a class="header-anchor" href="#where-next" aria-label="Permalink to &quot;Where Next&quot;">​</a></h2><ul><li><a href="./getting-started/installation">Installation</a> — panel addon (Blueprint or standalone) plus the node agent, with verification and troubleshooting.</li><li><a href="./getting-started/quick-start">Quick Start</a> — the five-minute path to your first detection.</li><li><a href="./configuration/reference">Configuration Reference</a> — every node config value and panel setting.</li><li><a href="./user-guide/admin-panel">Admin Panel</a> — a tour of all eight tabs.</li><li><a href="./architecture/overview">Architecture</a> — event pipeline, database schema, config versioning, failure modes.</li><li><a href="./architecture/detectors">Detectors</a> — what each of the 12 detectors watches and how it escalates.</li></ul>`,26))])}const A=i(p,[["render",g]]);export{v as __pageData,A as default};
